//! Differential oracle for `app::remote_annotation`.
//!
//! `fixtures/remote-annotation-golden.json` is the recorded answer of the
//! *deleted* Node module (`30cc801a^:src/remote-screen-rust.js`) — generated by
//! `/tmp/remote-annotation-diff/run.js`, which drove `isOwnShot` /
//! `handleAnnotation` over this corpus with a fake child process answering
//! each `FIXTURE_ANNOTATION` mode. The Rust front door must answer every case
//! byte-for-byte the same; a divergence here is a behaviour change hidden by
//! the port, not a test detail.
//!
//! `__DIR__` in the corpus is replaced with this test's screenshot directory so
//! the same fixture serves any machine.

use std::path::{Path, PathBuf};
use std::sync::Arc;
use std::time::Duration;

use serde_json::Value;

use multicc_gateway::app::remote_annotation::RemoteAnnotation;
use multicc_gateway::remote_child::{Config, RemoteChild};

mod common;
use common::fixture;

const GOLDEN: &str = include_str!("fixtures/remote-annotation-golden.json");

fn temp_dir(tag: &str) -> PathBuf {
    let stamp = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|elapsed| elapsed.as_micros())
        .unwrap_or(0);
    let dir = std::env::temp_dir().join(format!(
        "multicc-annotation-golden-{tag}-{}-{stamp}",
        std::process::id()
    ));
    std::fs::create_dir_all(&dir).expect("temp dir");
    dir
}

struct Harness {
    child: Arc<RemoteChild>,
    dir: PathBuf,
}

impl Harness {
    fn annotation(&self) -> RemoteAnnotation {
        RemoteAnnotation::new(Arc::clone(&self.child), self.dir.clone())
    }
}

fn harness(tag: &str, mode: &str, binary: Option<PathBuf>) -> Harness {
    let root = temp_dir(tag);
    let dir = root.join("remote-screen");
    std::fs::create_dir_all(&dir).expect("screenshot dir");
    let mut config = Config::new(dir.clone());
    config.binary = Some(binary.unwrap_or_else(fixture));
    config.ready_timeout = Duration::from_millis(400);
    config.restart_base = Duration::from_millis(20);
    config.restart_max = Duration::from_millis(200);
    config.stable_reset = Duration::from_millis(150);
    config.shutdown_grace = Duration::from_millis(500);
    config
        .env
        .push(("FIXTURE_ANNOTATION".to_string(), mode.to_string()));
    Harness {
        child: Arc::new(RemoteChild::new(config)),
        dir,
    }
}

/// Replace every `__DIR__` inside the corpus value with the real directory.
fn materialize(value: &Value, dir: &Path) -> Value {
    fn walk(value: &Value, dir: &str) -> Value {
        match value {
            Value::String(text) => Value::String(text.replace("__DIR__", dir)),
            Value::Array(items) => Value::Array(items.iter().map(|item| walk(item, dir)).collect()),
            Value::Object(map) => Value::Object(
                map.iter()
                    .map(|(key, item)| (key.clone(), walk(item, dir)))
                    .collect(),
            ),
            other => other.clone(),
        }
    }
    walk(value, &dir.to_string_lossy())
}

fn golden() -> Value {
    serde_json::from_str(GOLDEN).expect("golden fixture parses")
}

fn cases<'a>(golden: &'a Value, mode: &str) -> &'a Vec<Value> {
    golden["modes"][mode]
        .as_array()
        .unwrap_or_else(|| panic!("golden has a {mode} mode"))
}

#[tokio::test]
async fn every_recorded_node_case_answers_identically() {
    let golden = golden();
    let modes = golden["modes"].as_object().expect("modes object");
    assert!(modes.len() >= 6, "corpus lost a child mode: {modes:?}");

    for (mode, _) in modes {
        let h = harness(mode, mode, None);
        // Node's oracle used a 250 ms budget; the default here is 20 s and the
        // only mode that needs it to expire is `stall`.
        let mut annotation = h.annotation();
        if mode == "stall" {
            annotation = annotation.with_timeout(Duration::from_millis(250));
        }
        let recorded = cases(&golden, mode);
        let own_count = recorded.iter().filter(|case| case["own"] == true).count();
        assert!(own_count >= 1, "{mode} has no own-shot case");

        for case in recorded {
            let name = case["name"].as_str().expect("case name");
            let body = materialize(&case["body"], &h.dir);
            let expected = &case["result"];
            if case["own"].as_bool().expect("own flag") {
                assert!(
                    annotation.is_own_shot(&body),
                    "{mode}/{name}: should be own"
                );
                let relay = annotation
                    .try_relay(&body)
                    .await
                    .unwrap_or_else(|| panic!("{mode}/{name}: own shot must relay"));
                let results = relay["results"].as_array().expect("results");
                assert_eq!(results.len(), 1, "{mode}/{name}: one result");
                assert_eq!(
                    &results[0], expected,
                    "{mode}/{name}: answer differs from Node"
                );
                assert_eq!(relay["relayed"], 1, "{mode}/{name}");
            } else {
                assert!(
                    !annotation.is_own_shot(&body),
                    "{mode}/{name}: should not be own"
                );
                assert!(
                    annotation.try_relay(&body).await.is_none(),
                    "{mode}/{name}: a miss must not relay"
                );
                assert_eq!(
                    &annotation.handle_annotation(&body).await,
                    expected,
                    "{mode}/{name}: miss shape differs from Node"
                );
            }
        }
        h.child.shutdown().await;
    }
}

#[tokio::test]
async fn the_unavailable_group_matches_node() {
    let golden = golden();
    let group = &golden["unavailable"];
    let h = harness(
        "unavailable",
        "ok",
        Some(PathBuf::from("/nonexistent/multicc-remote")),
    );
    let body = materialize(&group["body"], &h.dir);
    assert_eq!(group["own"], true);
    assert!(h.annotation().is_own_shot(&body));
    let relay = h
        .annotation()
        .try_relay(&body)
        .await
        .expect("relayed even when the child is missing");
    assert_eq!(&relay["results"][0], &group["result"]);
    assert_eq!(h.child.snapshot().attempts, 0);
}
